package com.profa.course;import org.springframework.security.core.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/course-requests")public class CourseRequestController{final CourseRequestRepository r;public CourseRequestController(CourseRequestRepository r){this.r=r;}@GetMapping public List<CourseRequest> list(){return r.findAll();}@PostMapping@PreAuthorize("hasRole('PARENT')")public CourseRequest create(Authentication a,@RequestBody CourseRequest x){x.setParentId(UUID.fromString(a.getName()));return r.save(x);}@PatchMapping("/{id}/status")public CourseRequest status(@PathVariable UUID id,@RequestParam String value){CourseRequest x=r.findById(id).orElseThrow();x.setStatus(value);return r.save(x);}}